import { createSignal, splitProps, Show, type Component, type JSX } from "solid-js";
import { cn } from "@/lib/cn";

export interface CheckboxProps
  extends Omit<JSX.ButtonHTMLAttributes<HTMLButtonElement>, "onChange"> {
  /** Controlled checked state */
  checked?: boolean;
  /** Uncontrolled default checked state */
  defaultChecked?: boolean;
  /** Event handler triggered when checked state changes */
  onChange?: (checked: boolean) => void;
  class?: string;
}

/**
 * Nikala UI Checkbox component built for SolidJS with Tailwind CSS v4 styling.
 */
export const Checkbox: Component<CheckboxProps> = (props) => {
  // Use splitProps to preserve SolidJS reactivity
  const [local, rest] = splitProps(props, [
    "checked",
    "defaultChecked",
    "onChange",
    "disabled",
    "class",
    "onClick",
  ]);

  // Internal state for uncontrolled mode
  const [internalChecked, setInternalChecked] = createSignal(
    local.defaultChecked ?? false
  );

  // Computed checked state
  const isChecked = () =>
    local.checked !== undefined ? local.checked : internalChecked();

  const toggle = (
    e: MouseEvent & { currentTarget: HTMLButtonElement; target: Element }
  ) => {
    if (local.disabled) return;

    const nextState = !isChecked();
    if (local.checked === undefined) {
      setInternalChecked(nextState);
    }

    if (typeof local.onChange === "function") {
      local.onChange(nextState);
    }

    if (typeof local.onClick === "function") {
      local.onClick(e);
    }
  };

  return (
    <button
      type="button"
      role="checkbox"
      aria-checked={isChecked()}
      data-state={isChecked() ? "checked" : "unchecked"}
      disabled={local.disabled}
      onClick={toggle}
      class={cn(
        "peer h-4 w-4 shrink-0 rounded-sm border border-zinc-900 shadow focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-zinc-950 disabled:cursor-not-allowed disabled:opacity-50 data-[state=checked]:bg-zinc-900 data-[state=checked]:text-zinc-50 dark:border-zinc-100 dark:focus-visible:ring-zinc-300 dark:data-[state=checked]:bg-zinc-50 dark:data-[state=checked]:text-zinc-900 flex items-center justify-center transition-colors",
        local.class
      )}
      {...rest}
    >
      <Show when={isChecked()}>
        <svg
          class="h-3.5 w-3.5 fill-none stroke-current stroke-[3]"
          viewBox="0 0 24 24"
        >
          <path
            stroke-linecap="round"
            stroke-linejoin="round"
            d="M5 13l4 4L19 7"
          />
        </svg>
      </Show>
    </button>
  );
};
